    written: [
      { q: "दिनकर की दो रचनाओं के नाम लिखिए।", a: "कुरुक्षेत्र और रश्मिरथी (अन्य – उर्वशी)।", marks: 1 },
      { q: "‘जोखिम’ का अर्थ लिखिए।", a: "खतरा, संकट।", marks: 1 },
      { q: "निबंध में पानी के उदाहरण से लेखक क्या समझाता है?", a: "लेखक कहता है कि पानी के अमृत-तत्त्व को वही जानता है जो धूप में तपकर आया है। इसी प्रकार सुख का स्वाद उसी को आता है जो कठिनाई झेलता है। बिना कष्ट के सुख का मूल्य नहीं पता चलता।", marks: 3 },
      { q: "अकबर और पांडवों के उदाहरण क्यों दिए गए हैं?", a: "अकबर का जन्म साधनहीन परिस्थिति में हुआ पर वह महान सम्राट बना। पांडवों ने मुसीबतें झेलीं और अंत में विजयी हुए। इन उदाहरणों से बताया गया है कि कष्ट मनुष्य को शक्तिशाली बनाते हैं।", marks: 3 },
      { q: "‘अरे ओ जीवन के साधको’ से आरंभ होने वाले अंश का भाव लिखिए।", a: "लेखक जीवन के साधकों को ललकारता है कि निचली डाल का फल तोड़कर संतुष्ट न हों, फुनगी पर लगे आम तक पहुँचें। किनारे की सीपियों से संतोष न करें, समुद्र के मोती खोजें। वह इच्छाओं का आँचल बड़ा रखने को कहता है।", marks: 3 },
      { q: "‘हिम्मत और ज़िंदगी’ निबंध का सार लिखिए।", a: "1. असली मज़ा उन्हें मिलता है जो कठिनाई से गुज़रे हैं।\n2. आराम आसानी से पाने वालों के लिए आराम ही मौत है।\n3. अकबर, पांडव आदि संघर्ष की शक्ति के उदाहरण हैं।\n4. हिम्मत सबसे बड़ा गुण है।\n5. जोखिम से बचने वाला अपने ही घेरे में बंद रहता है; इसलिए बड़े लक्ष्य रखकर साहस से जीना चाहिए।", marks: 5 },
      { q: "दिनकर का साहित्यिक परिचय दीजिए।", a: "1. जन्म 1908 में सिमरिया (बिहार) में।\n2. पटना विश्वविद्यालय से बी.ए., सब-रजिस्ट्रार, फिर राज्यसभा सदस्य और भागलपुर विश्वविद्यालय के उपकुलपति।\n3. रचनाएँ – कुरुक्षेत्र, रश्मिरथी, उर्वशी।\n4. गद्य में ‘संस्कृति के चार अध्याय’ प्रसिद्ध।\n5. शैली ओजपूर्ण; निधन 1974 में।", marks: 5 },
      { q: "गद्यांश पर आधारित प्रश्न –\nरीना ने राज्य-स्तरीय वाद-विवाद में भाग लिया। पहली बार हारी, पर उसने कारण समझकर अभ्यास किया और अगले वर्ष विजयी बनी।\n(i) रीना में कौन-सा गुण दिखता है?\n(ii) दिनकर किस प्रकार के जीवन को श्रेष्ठ मानते हैं?\n(iii) असफलता से हमें क्या सीखना चाहिए?", a: "(i) हिम्मत और निरंतर प्रयास।\n(ii) जोखिम उठाकर लक्ष्य के लिए प्रयत्न करने वाले जीवन को।\n(iii) हार से निराश न होकर कारण समझना और पुनः प्रयास करना।", marks: 4, type: "case" }
    ]
